window.CODE = Object.assign(window.CODE || {}, {"ch03/prompt_eval.py":"\"\"\"Compare two prompt versions on the same labelled test set before you ship either.\n\nPrints accuracy, the errors on safety-critical labels, and tokens used, so you can pick\nthe better prompt on evidence instead of by feel. Run it after every prompt change.\n\nRun:  python prompt_eval.py\n\"\"\"\nimport json\nfrom pathlib import Path\n\nfrom prompts import CATEGORIES, FEW_SHOT, ZERO_SHOT, chat\n\nCASES = json.loads((Path(__file__).parent / \"test_messages.json\").read_text())\nCRITICAL = \"emergency\"          # a missed emergency is far worse than any other mistake\n\n\ndef run(prompt_name: str, system: str) -> dict:\n    correct, missed_critical, tokens, errors = 0, 0, 0, []\n    for case in CASES:\n        reply = chat(f\"Message: {case['message']}\", system=system, temperature=0, max_tokens=5)\n        tokens += reply[\"input_tokens\"] + reply[\"output_tokens\"]\n        got = reply[\"text\"].strip().lower().strip(\".\")\n        if got == case[\"label\"]:\n            correct += 1\n        else:\n            errors.append((case[\"message\"], case[\"label\"], got))\n            missed_critical += case[\"label\"] == CRITICAL\n    return {\"name\": prompt_name, \"accuracy\": correct / len(CASES), \"missed_emergencies\": missed_critical,\n            \"tokens\": tokens, \"errors\": errors}\n\n\nif __name__ == \"__main__\":\n    results = [run(\"v1 zero-shot\", ZERO_SHOT), run(\"v2 few-shot\", FEW_SHOT)]\n    print(f\"{'prompt':<14} {'accuracy':>8} {'missed emergencies':>19} {'tokens':>7}\")\n    for r in results:\n        print(f\"{r['name']:<14} {r['accuracy']:>8.0%} {r['missed_emergencies']:>19} {r['tokens']:>7}\")\n    for r in results:\n        for message, expected, got in r[\"errors\"]:\n            print(f\"  {r['name']}: '{message[:50]}' expected {expected}, got {got}\")\n    best = max(results, key=lambda r: (-r[\"missed_emergencies\"], r[\"accuracy\"], -r[\"tokens\"]))\n    print(f\"\\nShip: {best['name']}  (fewest missed emergencies first, then accuracy, then cost)\")\n    # check: every label in the test set is a valid category\n    assert all(c[\"label\"] in CATEGORIES for c in CASES)\n","ch03/prompts.py":"\"\"\"Zero-shot vs few-shot: sort helpdesk messages into categories.\n\nRun:  python prompts.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import chat\n\nCATEGORIES = [\"appointment\", \"billing\", \"complaint\", \"emergency\", \"other\"]\n\n# Zero-shot: instructions only, no examples.\nZERO_SHOT = f\"\"\"You sort messages sent to the City Clinic helpdesk.\nReply with exactly one word from this list: {\", \".join(CATEGORIES)}.\"\"\"\n\n# Few-shot: the same instructions plus worked examples. Examples teach the edge cases\n# that instructions alone leave vague, such as symptoms that must count as emergencies.\nFEW_SHOT = ZERO_SHOT + \"\"\"\n\nExamples:\nMessage: Can I see Dr Rao on Friday?                        -> appointment\nMessage: I was charged twice for my blood test.             -> billing\nMessage: The receptionist was rude to my mother.            -> complaint\nMessage: My father has chest pain and is sweating.          -> emergency\nMessage: Is there parking near the main gate?               -> other\nMessage: My PM-JAY card was not accepted at the counter.    -> billing\nMessage: I want to change my appointment and also complain. -> appointment\"\"\"\n\nMESSAGES = [\n    \"Can I move my Tuesday slot with Dr Iyer to Thursday?\",\n    \"Why does my bill show a consultation fee when it was a follow-up?\",\n    \"My child has a high fever and is not waking up properly.\",\n    \"Do you have a pharmacy inside the hospital?\",\n    \"Nobody answered the phone for 40 minutes, this is unacceptable.\",\n]\n\n\ndef classify(message: str, system: str) -> str:\n    reply = chat(f\"Message: {message}\", system=system, temperature=0, max_tokens=5)[\"text\"]\n    word = reply.strip().lower().strip(\".\")\n    return word if word in CATEGORIES else f\"?{word}\"\n\n\nif __name__ == \"__main__\":\n    print(f\"{'message':<62} {'zero-shot':<12} few-shot\")\n    for m in MESSAGES:\n        print(f\"{m[:60]:<62} {classify(m, ZERO_SHOT):<12} {classify(m, FEW_SHOT)}\")\n","ch03/reasoning.py":"\"\"\"Chain-of-thought: let the model work through the steps before answering.\n\nRun:  python reasoning.py\nThe numbers are made up. Real scheme rules must come from official documents, not the model.\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import chat\n\nPOLICY = \"\"\"City Clinic insurance desk rules (example only):\n- The scheme pays 80% of the cost of listed procedures.\n- The scheme pays room charges up to Rs 2,000 per day; the patient pays anything above.\n- Consumables (gloves, syringes) are not covered.\n- Everything the scheme pays counts towards a yearly limit of Rs 50,000.\"\"\"\n\nQUESTION = \"\"\"A patient had a listed procedure costing Rs 40,000, stayed 3 days in a Rs 3,000/day room,\nand used Rs 1,500 of consumables. They have already used Rs 25,000 of their yearly limit.\nHow much does the patient pay?\"\"\"\n\nDIRECT = \"Answer with only the final amount in rupees.\"\nSTEP_BY_STEP = (\"Work through the problem step by step: list each charge, apply each rule, check the yearly \"\n                \"limit, then add up. End with a line 'Patient pays: Rs <amount>'.\")\n\nif __name__ == \"__main__\":\n    for name, instruction in [(\"Direct answer\", DIRECT), (\"Step by step\", STEP_BY_STEP)]:\n        reply = chat(f\"{POLICY}\\n\\n{QUESTION}\\n\\n{instruction}\", temperature=0, max_tokens=500)\n        print(f\"\\n=== {name} ({reply['output_tokens']} output tokens) ===\\n{reply['text']}\")\n    # Correct working (Rs 25,500):\n    #   bill = 40,000 + 3 x 3,000 + 1,500 = 50,500\n    #   scheme would pay 80% x 40,000 = 32,000 plus 3 x 2,000 = 6,000, so 38,000\n    #   but only 50,000 - 25,000 = 25,000 of the yearly limit is left, so the scheme pays 25,000\n    #   patient pays 50,500 - 25,000 = 25,500\n","ch03/structured.py":"\"\"\"Structured output: turn a free-text message into validated data with Pydantic.\n\nThe model is asked for JSON that matches a schema. Pydantic checks it. If the check fails,\nthe error is sent back and the model gets one more try. This validate-and-retry loop\nworks with every provider and every model.\n\nRun:  pip install pydantic\n      python structured.py\n\"\"\"\nimport json\nimport sys\nfrom pathlib import Path\nfrom typing import Literal\n\nfrom pydantic import BaseModel, Field, ValidationError\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import chat\n\n\nclass AppointmentRequest(BaseModel):\n    patient_name: str | None = Field(None, description=\"Full name if given, else null\")\n    department: Literal[\"cardiology\", \"orthopaedics\", \"paediatrics\", \"unknown\"]\n    doctor: str | None = Field(None, description=\"Doctor's name if mentioned, e.g. 'Dr Rao'\")\n    preferred_days: list[Literal[\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"]] = []\n    urgent: bool = Field(description=\"True if the message mentions severe or emergency symptoms\")\n\n\nSYSTEM = (\"You extract appointment details from messages sent to City Clinic. \"\n          \"Reply with JSON only, no other text, matching this JSON Schema:\\n\"\n          + json.dumps(AppointmentRequest.model_json_schema()))\n\n\ndef extract(message: str, retries: int = 1) -> AppointmentRequest:\n    prompt = f\"Message: {message}\"\n    for attempt in range(retries + 1):\n        text = chat(prompt, system=SYSTEM, temperature=0, max_tokens=300)[\"text\"]\n        text = text.strip().removeprefix(\"```json\").removeprefix(\"```\").removesuffix(\"```\").strip()\n        try:\n            return AppointmentRequest.model_validate_json(text)\n        except ValidationError as err:\n            if attempt == retries:\n                raise\n            # Send the exact problem back so the model can correct itself.\n            prompt = (f\"Message: {message}\\n\\nYour previous reply was invalid:\\n{text}\\n\\n\"\n                      f\"Errors:\\n{err}\\n\\nReply again with corrected JSON only.\")\n\n\nif __name__ == \"__main__\":\n    for msg in [\"Hi, I'm Asha Verma. Can I see the bone doctor, Dr Iyer, on Tuesday or Thursday?\",\n                \"my son (6) has had a rash for two days, any day next week is fine\",\n                \"Chest pain since morning, need cardiology today please. Ravi Kumar.\"]:\n        req = extract(msg)\n        print(req.model_dump_json(indent=2))\n","ch03/test_messages.json":"[\n  {\"message\": \"Can I see Dr Mehta next Wednesday?\", \"label\": \"appointment\"},\n  {\"message\": \"Please reschedule my Friday paediatrics visit to Monday.\", \"label\": \"appointment\"},\n  {\"message\": \"Is Dr Khan available this week for my daughter?\", \"label\": \"appointment\"},\n  {\"message\": \"I was billed for an X-ray I never had.\", \"label\": \"billing\"},\n  {\"message\": \"My insurance claim number is not showing on the invoice.\", \"label\": \"billing\"},\n  {\"message\": \"Does the scheme cover the MRI my doctor ordered?\", \"label\": \"billing\"},\n  {\"message\": \"The waiting area was dirty and nobody cleaned it.\", \"label\": \"complaint\"},\n  {\"message\": \"I waited 3 hours past my slot without any update.\", \"label\": \"complaint\"},\n  {\"message\": \"My mother collapsed and is not responding.\", \"label\": \"emergency\"},\n  {\"message\": \"Severe chest pain and my left arm feels numb.\", \"label\": \"emergency\"},\n  {\"message\": \"My baby is breathing very fast and looks blue.\", \"label\": \"emergency\"},\n  {\"message\": \"What time does the canteen open?\", \"label\": \"other\"},\n  {\"message\": \"Is there a wheelchair at the entrance?\", \"label\": \"other\"},\n  {\"message\": \"I want to book a slot, and also the doctor was rude last time.\", \"label\": \"appointment\"}\n]\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
